def check_solutions(b):
    target = 2**(b+1) - 1
    print(f"--- Checking b = {b}. Target sum = {target} ---")

    # Case 1: 3^y + 2 * 3^(b-y) = target
    found_c1 = False
    for y in range(b + 1):
        w = b - y
        lhs = 3**y + 2 * (3**w)
        if lhs == target:
            found_c1 = True
            print(f"Case 1 Solution found: y={y}, w={w}. LHS = {lhs}")
        elif lhs > target and y > 0:
            # If y increases, 3^y increases rapidly. We can stop early if we are far off.
            # Since w decreases, 2*3^w decreases, but the overall value often increases fast enough.
            # A precise break is hard due to the interplay, but we can skip if we exceed target substantially.
            pass # Continue checking other y values just in case
        elif lhs < target and y == b:
            # Check y=b case explicitly: 3^b + 2*1. If this is < target, no larger y can help.
            break
    if not found_c1:
        print("Case 1: No solutions found.")

    # Case 2: 2 * 3^y + 3^(b-y) = target
    found_c2 = False
    for y in range(b + 1):
        w = b - y
        lhs = 2 * (3**y) + 3**w
        if lhs == target:
            found_c2 = True
            print(f"Case 2 Solution found: y={y}, w={w}. LHS = {lhs}")
        elif lhs > target and y > 0:
            # Similar stopping logic applies
            pass
        elif lhs < target and y == 0:
            # Check y=0 case explicitly: 2 + 3^b. If this is < target, no smaller y can help.
            break
    if not found_c2:
        print("Case 2: No solutions found.")

for b_test in [6, 7, 8, 9, 10]:
    check_solutions(b_test)

